window.docContents[34].resolve({"/rules/RG1001/#RG1001-proof-shape":{"contents":"A conditional result must carry the assumption in its type, for example ∀ (h : P), Q, so the exact theorem statement shows what it depends on. Its transitive axiom set must then fit the surface's foundation profile.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1001: Project logical axioms are forbidden","header":"Required proof shape","id":"/rules/RG1001/#RG1001-proof-shape"}});